import { readFileSync } from "node:fs";
import path from "node:path";

/**
 * Quran data, read from src/data/quran/ (generated by scripts/import-quran.mjs).
 * Synchronous reads keep pages fully prerendered under Cache Components.
 */
const DATA_DIR = path.join(process.cwd(), "src", "data", "quran");

export type SurahMeta = {
  number: number;
  ayahs: number;
  revelationOrder: number;
  rukus: number;
  nameArabic: string;
  transliteration: string;
  meaningEn: string;
  type: "makki" | "madani";
};

export type Verse = {
  n: number;
  /** Uthmani Arabic, exactly as published. */
  ar: string;
  ur: string;
  en: string;
  urNotes?: string;
  enNotes?: string;
};

export type QuranSources = {
  translations: Record<"ur" | "en", { key: string; title: string; version: string }>;
};

let surahList: SurahMeta[] | undefined;

export function getSurahList(): SurahMeta[] {
  surahList ??= JSON.parse(readFileSync(path.join(DATA_DIR, "surahs.json"), "utf8")) as SurahMeta[];
  return surahList;
}

export function getSurahMeta(number: number): SurahMeta | undefined {
  return getSurahList()[number - 1];
}

export function getSurahVerses(number: number): Verse[] {
  const file = path.join(DATA_DIR, "surahs", `${String(number).padStart(3, "0")}.json`);
  return (JSON.parse(readFileSync(file, "utf8")) as { verses: Verse[] }).verses;
}

export function getQuranSources(): QuranSources {
  return JSON.parse(readFileSync(path.join(DATA_DIR, "sources.json"), "utf8")) as QuranSources;
}

/** Parses "1".."114" (no leading zeros, so each surah has one URL); anything else returns null. */
export function parseSurahNumber(value: string): number | null {
  if (!/^[1-9]\d{0,2}$/.test(value)) return null;
  const n = Number(value);
  return n >= 1 && n <= 114 ? n : null;
}

/** The Bismillah is printed above every surah except Al-Fatihah (where it is verse 1) and At-Tawbah. */
export function showsBismillah(surah: number): boolean {
  return surah !== 1 && surah !== 9;
}
